insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_141'
from (values
('127.888.d.26.A',3,'A student sorts fires into wood and paper, flammable liquids, electrical and metal fires, and maps the fire zones of an airplane. She is:','["explaining types of fires and aircraft fire zones", "describing seats", "ignoring fires", "describing tires"]'::jsonb,0,'Fire classes and zones.','original'),
('127.888.d.26.A',4,'A Class B fire involves:','["electrical shorts only", "flammable liquids such as fuel", "metals", "wood and paper"]'::jsonb,1,'Class B.','original'),
('127.888.d.26.B',3,'A student labels the sensing element, control unit and warning light of an overheat detection system. She is:','["avoiding detectors", "describing seats", "identifying the components and explaining the basic operation of overheat detection systems", "describing tires"]'::jsonb,2,'Overheat detection.','original'),
('127.888.d.26.B',4,'A continuous-loop overheat detector reacts when:','["the cabin is dark", "the radio is on", "the loop gets cold", "a section of the loop gets too hot"]'::jsonb,3,'Loop detector.','original'),
('127.888.d.26.C',3,'A student traces a fire detector to the cockpit warning bell and light and the extinguisher handle. She is:','["identifying the components and explaining the basic operation of fire detection and warning systems", "describing tires", "avoiding detectors", "describing seats"]'::jsonb,0,'Fire detection.','original'),
('127.888.d.26.C',4,'A fire warning system is designed to alert the crew to:','["a radio call", "an actual fire in a protected zone", "a low tire", "a full tank"]'::jsonb,1,'Fire warning.','original'),
('127.888.d.26.D',3,'A student studies a cargo-bay smoke detector and a lavatory carbon monoxide sensor. She is:','["describing seats", "avoiding detectors", "identifying the components and explaining the basic operation of smoke and carbon monoxide detection systems", "describing tires"]'::jsonb,2,'Smoke and CO.','original'),
('127.888.d.26.D',4,'A carbon monoxide detector is especially important in aircraft that have:','["no windows", "no cabin", "no engine", "exhaust-heated cabin heat"]'::jsonb,3,'CO risk.','original'),
('127.888.d.26.E',3,'A student compares a halon bottle, a CO2 bottle and a dry chemical extinguisher by the agent each holds. She is:','["describing types of fire extinguishing systems and extinguishing agents", "avoiding fire", "describing seats", "describing tires"]'::jsonb,0,'Agents.','original'),
('127.888.d.26.E',4,'An engine fire bottle works by:','["adding fuel", "releasing an agent into the protected zone when the squib fires", "stopping the radio", "cooling the cabin"]'::jsonb,1,'Agent release.','original'),
('127.888.d.26.F',3,'A technician is told to disarm the squib circuits before testing the fire system wiring. She is researching:','["no risks", "tire brands", "the risks of maintenance on circuits associated with fire protection", "paint choices"]'::jsonb,2,'Squib safety.','original'),
('127.888.d.26.F',4,'Disarming an extinguisher squib before maintenance prevents:','["a quiet cabin", "a dry hangar", "a bright light", "accidental discharge of the extinguishing agent"]'::jsonb,3,'Disarm squib.','original'),
('127.888.d.26.G',3,'A mechanic wears gloves, eye protection and a respirator when servicing a fire bottle. She is researching:','["the use of PPE when working on or testing fire extinguishing systems", "paint choices", "no PPE", "tire brands"]'::jsonb,0,'Fire PPE.','original'),
('127.888.d.26.G',4,'Fire extinguishing agent containers are high pressure, so a mechanic should handle them:','["roughly", "carefully, with the protective cap in place", "without caps", "by dropping them"]'::jsonb,1,'Cap on.','original'),
('127.888.d.26.H',3,'A student reads that breathing in some extinguishing agents in a closed space can be harmful. She is explaining:','["no risks", "tire brands", "the risks of exposure to fire extinguishing agents", "paint choices"]'::jsonb,2,'Agent exposure.','original'),
('127.888.d.26.H',4,'An extinguishing agent discharged in a small space can displace oxygen, so the area should be:','["sealed", "darkened", "heated", "ventilated before anyone enters"]'::jsonb,3,'Ventilate.','original'),
('127.888.d.27.A',3,'A mechanic reads the gauge on a fire bottle and compares the pressure to a temperature chart. She is:','["evaluating an installed fire extinguisher system for proper container pressure", "guessing", "painting the bottle", "ignoring the gauge"]'::jsonb,0,'Bottle pressure.','original'),
('127.888.d.27.A',4,'A fire bottle''s correct pressure depends on its:','["seat position", "temperature at the time of the check", "paint color", "tire size"]'::jsonb,1,'Temp chart.','original'),
('127.888.d.27.B',3,'A technician opens the manual to the steps for testing a cabin smoke detector using a test button or aerosol. She is:','["ignoring detectors", "painting detectors", "locating and explaining the procedures for checking a smoke detection system", "guessing"]'::jsonb,2,'Smoke test.','original'),
('127.888.d.27.B',4,'A smoke detector test should confirm that the:','["radio works", "tires hold air", "seat reclines", "alarm sounds and indicator light work"]'::jsonb,3,'Alarm check.','original'),
('127.888.d.27.C',3,'A technician follows the manual to check the continuous loop for chafing, kinks and loose connectors. She is:','["locating and explaining the procedures for inspecting an overheat detection system", "painting the loop", "guessing", "ignoring the loop"]'::jsonb,0,'Overheat inspection.','original'),
('127.888.d.27.C',4,'A kinked or chafed detector loop could lead to:','["better detection", "a false alarm or a failure to detect heat", "a stronger loop", "no change"]'::jsonb,1,'Loop damage.','original'),
('127.888.d.27.D',3,'A mechanic checks the stamped date on a fire bottle against the required test interval. She is:','["ignoring dates", "dumping cylinders", "inspecting fire protection system cylinders and checking for the hydrostatic test date", "painting cylinders"]'::jsonb,2,'Hydro date.','original'),
('127.888.d.27.D',4,'A cylinder past its hydrostatic test date must be:','["ignored", "used anyway", "painted", "retested or replaced before use"]'::jsonb,3,'Overdue cylinder.','original'),
('127.888.d.28.A',3,'A student explains how a helicopter rotor produces lift and how the cyclic and collective change it. She is:','["explaining the characteristics of rotorcraft aerodynamics and flight controls", "describing airplanes only", "describing seats", "describing tires"]'::jsonb,0,'Rotor aerodynamics.','original'),
('127.888.d.28.A',4,'The collective control changes the pitch of:','["one blade only", "all the main rotor blades together", "the landing skids", "the tail rotor only"]'::jsonb,1,'Collective.','original'),
('127.888.d.28.B',3,'A student labels the main rotor gearbox, tail rotor gearbox and freewheeling unit. She is:','["describing tires", "describing seats", "identifying the components and explaining the function of rotorcraft transmissions", "avoiding gearboxes"]'::jsonb,2,'Helicopter transmission.','original'),
('127.888.d.28.B',4,'A freewheeling unit allows the main rotor to:','["speed up with the engine", "stop with the engine", "spin backward", "keep turning if the engine stops"]'::jsonb,3,'Autorotation clutch.','original'),
('127.888.d.28.C',3,'A mechanic learns why control linkages on a helicopter must be rigged to exact specifications. She is:','["explaining the need for rigging requirements for rotary wing aircraft", "ignoring rigging", "describing seats", "describing tires"]'::jsonb,0,'Rotor rigging.','original'),
('127.888.d.28.C',4,'Incorrect helicopter rigging could cause:','["less noise", "incorrect control response and vibration", "more lift", "perfect control"]'::jsonb,1,'Rig errors.','original'),
('127.888.d.28.D',3,'A student compares fully articulated, semirigid and rigid rotor systems and the construction of their blades. She is:','["describing tires", "describing seats", "identifying rotor systems, rotor blade functions and rotor blade construction", "avoiding rotors"]'::jsonb,2,'Rotor systems.','original'),
('127.888.d.28.D',4,'A semirigid rotor system is commonly found on:','["a jet fighter", "a glider", "a balloon", "a two-bladed helicopter with a teetering hub"]'::jsonb,3,'Semirigid.','original'),
('127.888.d.28.E',3,'A mechanic checks skid shoes for wear and skid tubes for cracks and corrosion. She is:','["explaining the need for helicopter skid shoe and tube inspections", "ignoring skids", "painting skids", "adding weight"]'::jsonb,0,'Skid inspection.','original'),
('127.888.d.28.E',4,'Worn skid shoes should be replaced to protect the:','["rotor blades", "skid tubes", "windshield", "tail rotor"]'::jsonb,1,'Skid shoes.','original'),
('127.888.d.28.F',3,'A student connects a low, steady one-per-revolution shake to an out-of-balance main rotor. She is:','["describing tires", "ignoring vibration", "explaining causes of rotor system and drive system vibrations", "describing seats"]'::jsonb,2,'Rotor vibration.','original'),
('127.888.d.28.F',4,'A worn driveshaft coupling can cause:','["a cooler engine", "no vibration", "a quieter cabin", "a high-frequency vibration"]'::jsonb,3,'Drive vibration.','original'),
('127.888.d.28.G',3,'A technician explains that tracking makes all the blades follow the same path and balancing evens out their weight. She is:','["explaining the purpose of rotor blade track and balance", "describing seats", "describing tires", "avoiding blades"]'::jsonb,0,'Track and balance.','original'),
('127.888.d.28.G',4,'A rotor blade that is out of track will usually cause:','["better lift", "vibration in flight", "less drag", "a smoother ride"]'::jsonb,1,'Out of track.','original'),
('127.888.d.28.H',3,'A student reads why a person should not walk toward a turning rotor from the high side or from behind. She is researching:','["no risks", "paint choices", "the risks of working around helicopter blades during ground operations", "tire brands"]'::jsonb,2,'Blade hazards.','original'),
('127.888.d.28.H',4,'A main rotor can dip low on startup and shutdown, so ground crews should approach:','["without looking", "from behind", "from the high side", "only when signaled by the pilot and from the front, in view"]'::jsonb,3,'Approach rules.','original'),
('127.888.d.28.I',3,'A student reads that towing a helicopter without a proper tow bar and ground crew can cause an accident. She is researching:','["the risks of improper ground handling procedures", "no risks", "tire brands", "paint choices"]'::jsonb,0,'Ground handling.','original'),
('127.888.d.28.I',4,'When moving a helicopter on the ground, the ground crew should use:','["a car", "approved ground-handling equipment and a spotter", "a rope only", "no help"]'::jsonb,1,'Handling gear.','original'),
('127.888.d.28.J',3,'A mechanic is warned about running the engine and rotor on the ground without securing the area. She is researching:','["paint choices", "tire brands", "the risks of ground operations and functional tests", "no risks"]'::jsonb,2,'Ground runs.','original'),
('127.888.d.28.J',4,'Before a ground run, the crew should clear the area and:','["turn off lights", "open all doors", "invite spectators", "keep bystanders away from the rotor disk"]'::jsonb,3,'Clear the area.','original'),
('127.888.d.28.K',3,'A technician is told that a missed cotter pin on a flight control rod end can have deadly results. She is researching:','["the risks of improper maintenance of rotorcraft systems", "tire brands", "no risks", "paint choices"]'::jsonb,0,'Rotor maintenance.','original'),
